def _point_segment(p,a,b):
    p,a,b=map(lambda v:np.asarray(v,float),(p,a,b));d=b-a
    if not np.dot(d,d)>0:raise ValueError('zero length passage')
    return float(np.linalg.norm(p-(a+np.clip(np.dot(p-a,d)/np.dot(d,d),0,1)*d)))

